// The browser's emoji vocabulary (issue #763): the Unicode Emoji catalog
// (catalog.json, generated by `go generate ./pkg/schema` from the pinned
// emoji-test.txt) as a searchable index, and `:shortcode:` completion.
//
// Shortcodes are derived, not vendored. Unicode publishes CLDR short names, not
// shortcodes, so the vocabulary is the name made lower case with underscores
// (see shortcodeOf). It is a client vocabulary for typing; it never travels on
// the wire. What is inserted is the catalog's key, the fully-qualified
// sequence (docs/design/message-reactions.md section 3.2).
import { EMOJI_VERSION } from '../schema/reaction';
import catalog from './catalog.json';

export interface Emoji {
  // The fully-qualified sequence, as inserted.
  readonly key: string;
  // The CLDR short name.
  readonly name: string;
  // The derived :shortcode: without its colons.
  readonly shortcode: string;
  readonly group: string;
  readonly subgroup: string;
  // A skin-tone variant: found by search, not listed when browsing a group.
  readonly toned: boolean;
}

export interface EmojiGroup {
  readonly name: string;
  // Every entry, in the catalog's order.
  readonly emoji: readonly Emoji[];
  // The entries a browse lists: the variants of a skin tone are left out.
  readonly browse: readonly Emoji[];
}

export interface EmojiIndex {
  readonly version: string;
  readonly groups: readonly EmojiGroup[];
  readonly all: readonly Emoji[];
}

export interface RawCatalog {
  readonly version: string;
  readonly groups: readonly {
    readonly name: string;
    readonly subgroups: readonly { readonly name: string; readonly emoji: readonly { readonly key: string; readonly name: string }[] }[];
  }[];
}

// The shortcode rule: take the CLDR name; drop accents; drop apostrophes; read
// '#', '*' and '&' as words (so the two keycaps differ); lower-case; every run
// of anything but a-z and 0-9 becomes one '_'; trim '_'. "thumbs up: medium skin
// tone" is :thumbs_up_medium_skin_tone:, "twelve o'clock" is :twelve_oclock:.
export function shortcodeOf(name: string): string {
  return name
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/['’]/g, '')
    .replace(/#/g, ' hash ')
    .replace(/\*/g, ' asterisk ')
    .replace(/&/g, ' and ')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '');
}

export function buildIndex(raw: RawCatalog): EmojiIndex {
  const all: Emoji[] = [];
  const groups: EmojiGroup[] = [];
  for (const g of raw.groups) {
    const emoji: Emoji[] = [];
    for (const s of g.subgroups) {
      for (const e of s.emoji) {
        emoji.push({ key: e.key, name: e.name, shortcode: shortcodeOf(e.name), group: g.name, subgroup: s.name, toned: e.name.includes('skin tone') });
      }
    }
    all.push(...emoji);
    groups.push({ name: g.name, emoji, browse: emoji.filter((e) => !e.toned) });
  }
  return { version: raw.version, groups, all };
}

let built: EmojiIndex | null = null;

// The index is built from the catalog the first time a picker or a completion
// needs it, not at start-up. The catalog is bundled (no dynamic import: the
// hygiene test allows none), so this is a promise only so that a split chunk
// could replace it without a caller changing.
export function loadEmoji(): Promise<EmojiIndex> {
  if (built === null) {
    const index = buildIndex(catalog);
    if (index.version !== EMOJI_VERSION) return Promise.reject(new Error(`emoji catalog ${index.version} does not match the schema's ${EMOJI_VERSION}`));
    built = index;
  }
  return Promise.resolve(built);
}

const fold = (s: string) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

// Search: every word of the query must be in the name or the shortcode. Names
// that start with the query come first, then names with a word that starts with
// it, then the rest; within each, the catalog's order.
export function searchEmoji(index: EmojiIndex, query: string, limit = 120): Emoji[] {
  const terms = fold(query).split(/[\s_]+/).filter((t) => t !== '');
  if (terms.length === 0) return [];
  const phrase = terms.join(' ');
  const first = terms[0] ?? '';
  const ranked: { e: Emoji; rank: number; at: number }[] = [];
  index.all.forEach((e, at) => {
    const name = fold(e.name);
    if (!terms.every((t) => name.includes(t) || e.shortcode.includes(t))) return;
    const rank = e.shortcode === terms.join('_') ? -1 : name.startsWith(phrase) ? 0 : name.split(/[^a-z0-9]+/).some((w) => w.startsWith(first)) ? 1 : 2;
    ranked.push({ e, rank, at });
  });
  ranked.sort((a, b) => a.rank - b.rank || a.at - b.at);
  return ranked.slice(0, limit).map((r) => r.e);
}

export const completionMinQuery = 2;
export const completionMax = 8;

export interface Completion {
  // Where the ':' is, and the typed text after it.
  readonly start: number;
  readonly query: string;
}

// The `:short` the caret is at the end of, if any. The colon must start the
// text or follow a space, a line break or an opening bracket, so "12:30" and a
// URL do not open it, and the query holds only what a shortcode holds.
export function completionAt(text: string, caret: number): Completion | null {
  const before = text.slice(0, caret);
  const m = /(^|[\s([{])(:)([a-z0-9_]*)$/i.exec(before);
  if (m === null) return null;
  const query = m[3] ?? '';
  if (query.length < completionMinQuery) return null;
  return { start: before.length - query.length - 1, query: query.toLowerCase() };
}

// The shortcode that is the query comes first, then those that start with it,
// then those that contain it.
export function completeShortcode(index: EmojiIndex, query: string, limit = completionMax): Emoji[] {
  const exact: Emoji[] = [];
  const prefix: Emoji[] = [];
  const inside: Emoji[] = [];
  for (const e of index.all) {
    if (e.shortcode === query) exact.push(e);
    else if (e.shortcode.startsWith(query)) prefix.push(e);
    else if (e.shortcode.includes(query)) inside.push(e);
    if (prefix.length >= limit) break;
  }
  return [...exact, ...prefix, ...inside].slice(0, limit);
}

// Put `insert` where the selection is, in place of the selection; the caret goes
// after it.
export function insertAt(text: string, from: number, to: number, insert: string): { text: string; caret: number } {
  const a = Math.max(0, Math.min(from, to, text.length));
  const b = Math.min(text.length, Math.max(from, to));
  return { text: text.slice(0, a) + insert + text.slice(b), caret: a + insert.length };
}
